PYGD_HELP = [
    "# pygdeep - تلوين الشيفرة العميق: كل المُحلّلات والمُنسّقات والأنماط (pygments)",
]

_PYGD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _pygdeep_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in PYGD_CONSTS:
        return PYGD_CONSTS[word]
    if word in PYGD_FUNCS:
        return PYGD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def PYGD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _PYGD_TOKEN.sub(_pygdeep_replace, text)
